"""Publish front-first and correctly oriented side silhouette review evidence."""
from pathlib import Path
import hashlib,json,re,subprocess
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/art/creature-models/2026-10-13/rift-titan-silhouette-r7'
row=json.loads((OUT/'refinement-metrics.json').read_text());ID=row['id']
checks=json.loads((OUT/'verification.json').read_text());contacts=json.loads((OUT/'attachment-verification.json').read_text());direction=json.loads((OUT/'side-orientation.json').read_text())
assert row['triangles']==checks['triangles']==1800 and contacts['result']=='PASS' and contacts['endpoints']==50
assert checks['source_sha256']==direction['source_sha256']==hashlib.sha256((ROOT/row['source']).read_bytes()).hexdigest()
assert direction['camera_direction'][0]<0
torso=json.loads((OUT/'torso-authoring.json').read_text());torso.update(scope='r6 ring topology retained within the r7 whole-creature spatial fit; all collar, rib, band and neck contacts reseated',parameter_units='r6 authored ring dimensions precede r7 width/height fitting and final uniform study scaling')
(OUT/'torso-authoring.json').write_text(json.dumps(torso,indent=2)+'\n',encoding='utf-8')
auth=json.loads((OUT/'silhouette-authoring.json').read_text());auth['torso_width_fit']=1.10
(OUT/'silhouette-authoring.json').write_text(json.dumps(auth,indent=2)+'\n',encoding='utf-8')
for name in ('band-verification','collar-verification'):assert json.loads((OUT/(name+'.json')).read_text())['result']=='PASS'
html=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rift Titan — front and left-facing side silhouette r7</title>
<style>body{{background:#14191c;color:#e4e5df;font:16px system-ui;max-width:1500px;margin:auto;padding:24px}}p{{line-height:1.6;max-width:1150px}}a{{color:#9ccdda}}img{{width:100%;object-fit:contain;background:#171e22}}.pair{{display:grid;grid-template-columns:1fr 1fr;gap:14px}}.reference img{{height:650px}}figure{{margin:0}}figcaption{{padding:8px;color:#bbc5c6}}button{{background:#283840;color:#e4e5df;border:1px solid #60747a;padding:8px 14px;margin:5px;cursor:pointer}}@media(max-width:800px){{.pair{{grid-template-columns:1fr}}.reference img{{height:500px}}}}</style>
<h1>Rift Titan — front, then left-facing side silhouette r7</h1>
<p>This pass concentrates on shape. The frontal fit has one long fractured head with an uneven central peak, broader shoulder and limb stone masses, a narrower overall arm spread and a revised head/body/leg proportion. Four former floating stones now form paired upper and lower torso masses. The side fit gives the stone plates tapered depth, a forward head and cage, and fuller knees and feet. The two closed torso rings and continuous ribs remain.</p>
<p><strong>Side direction is fixed: front/head left, back right.</strong> The saved models are rendered from that side; a projection check rejects the opposite-facing camera. The r5/r6 comparisons were corrected as well.</p>
<p><strong>1,800 triangles · 1.500× native Stone Golem · soft cap 1,800</strong>. One mesh/material and four 512px maps. All fifty support contacts pass 35 sampled action poses. The original eight-bone hierarchy and seven actions remain, with rest positions fitted to the revised shape. This is a silhouette candidate for visual review; texture detail is deferred.</p>
<h2>Front silhouette first</h2><div class="pair reference"><figure><img src="concept-front.png" alt="Supplied frontal Rift Titan concept"><figcaption>Concept front</figcaption></figure><figure><img src="{ID}--front-reference.png" alt="Current frontal clay silhouette"><figcaption>Current front — clay, with framing fitted to the supplied reference</figcaption></figure></div>
<h2>Then the left-facing side</h2><div class="pair reference"><figure><img src="concept-side.png" alt="Supplied left-facing side concept"><figcaption>Concept side — front left, back right</figcaption></figure><figure><img src="{ID}--side-reference-clay.png" alt="Current left-facing clay view"><figcaption>Current left-facing view — front-biased angle for comparison with the concept</figcaption></figure></div>
<h2>Before and after — matched cameras</h2><div><button data-view="front-clay">Front clay</button><button data-view="side-clay">True side clay</button><button data-view="side-reference">Left-facing angled side</button></div><div class="pair"><figure><img id="before" src="before/underworld-boss-rift-titan-wrap-r6--front-clay.png" alt="Preserved r6 silhouette"><figcaption>Previous r6 — preserved model, re-rendered with the matching camera</figcaption></figure><figure><img id="after" src="{ID}--front-clay.png" alt="Current r7 silhouette"><figcaption>Current r7 — front-first mass and profile fit</figcaption></figure></div>
<h2>Full adopted concept</h2><img src="../../../creature-concepts/2026-10-03/the-rift-titan.png" alt="Full adopted Rift Titan concept sheet">
<p>The silhouette is under review. The concept's finer fractured edges and surface weathering remain unfinished; no exact-match or adequate boss acceptance is inferred from the checks. Native admission, full animation deformation and live performance remain separate.</p>
<p><a href="../../../../../{row['source']}">Editable Blender model</a> · <a href="{ID}.glb">Skinned export</a> · <a href="{ID}--three-quarter.png">Surface view</a> · <a href="{ID}--detail.png">Torso close-up</a> · <a href="{ID}--attack.png">Attack pose</a> · <a href="verification.json">Geometry/export checks</a> · <a href="attachment-verification.json">Support checks</a> · <a href="silhouette-measurements.json">Saved proportions</a> · <a href="side-orientation.json">Side orientation</a> · <a href="silhouette-authoring.json">Shape changes</a> · <a href="provenance.json">Source provenance</a></p>
<script>document.querySelectorAll('button[data-view]').forEach(b=>b.onclick=()=>{{document.getElementById('before').src='before/underworld-boss-rift-titan-wrap-r6--'+b.dataset.view+'.png';document.getElementById('after').src='{ID}--'+b.dataset.view+'.png';}});</script></html>'''
sources=['tools/rift_titan_r4_base.py','tools/rift_titan_primary_layout.py','tools/rift_titan_rock_facets.py','tools/rift_titan_wrapped_torso.py','tools/rift_titan_silhouette_fit.py','tools/refine-rift-titan-silhouette-r7.py','tools/review-rift-titan-wrap-r6.py','tools/review-rift-titan-silhouette-r7.py','tools/review-rift-titan-silhouette-before-r7.py','tools/verify-rift-titan-silhouette-r7.py','tools/publish-rift-titan-silhouette-r7.py',row['source'],'assets/models/studies/underworld-boss-rift-titan-wrap-r6.blend','docs/art/creature-concepts/2026-10-03/the-rift-titan.png']+[p.relative_to(ROOT).as_posix() for p in OUT.glob('concept-*.png')]
(OUT/'provenance.json').write_text(json.dumps(dict(base_commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),hashes={p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in sources},acceptance='unaccepted front/side silhouette candidate; adequate boss tally remains 1/6'),indent=2)+'\n',encoding='utf-8')
(OUT/'gallery.html').write_text(html,encoding='utf-8')
for target in re.findall(r'(?:href|src)="([^"]+)"',html):assert (OUT/target).resolve().is_file(),target
for view in ('front-clay','side-clay','side-reference'):
 assert (OUT/'before'/('underworld-boss-rift-titan-wrap-r6--'+view+'.png')).is_file()
 assert (OUT/(ID+'--'+view+'.png')).is_file()
print('VERIFIED front/left-side review links, cap and saved source provenance')
